import { useFunnel } from '@use-funnel/react-router-dom';
import { FunnelStep } from '~/widgets/exchange-payment-funnel/model/enums';
import {
  FunnelContextMap,
  금액입력_Schema,
  금액확인_Schema,
  완료_Schema,
  처리중_Schema,
} from '~/widgets/exchange-payment-funnel/model/schemas';
import { BaseExchangeContext } from '~/entities/exchange';

export const usePaymentFunnel = (initialConfig?: { step?: FunnelStep; context?: Partial<BaseExchangeContext> }) => {
  const initialStep = initialConfig?.step || FunnelStep.금액확인;
  const initialContext = {
    ...(initialConfig?.context || {}),
  };

  const funnel = useFunnel<FunnelContextMap>({
    id: 'payment-funnel',
    steps: {
      [FunnelStep.금액입력]: { parse: 금액입력_Schema.parse },
      [FunnelStep.금액확인]: { parse: 금액확인_Schema.parse },
      [FunnelStep.처리중]: { parse: 처리중_Schema.parse },
      [FunnelStep.완료]: { parse: 완료_Schema.parse },
    },
    initial: {
      step: initialStep,
      context: initialContext,
    },
  });

  return {
    funnel,
  };
};
